    if frequency is None or frequency == "always":
        return None
    match = re.match(r"(\d+) (\w+)", frequency)
    if not match:
        raise ValueError(f"Invalid frequency: {frequency}")
    num, unit = match.groups()
    if unit == "weeks":
        return datetime.timedelta(weeks=int(num))
    elif unit == "days":
        return datetime.timedelta(days=int(num))
    elif unit == "hours":
        return datetime.timedelta(hours=int(num))
    elif unit == "minutes":
        return datetime.timedelta(minutes=int(num))
    elif unit == "seconds":
        return datetime.timedelta(seconds=int(num))
    else:
        raise ValueError(f"Invalid unit: {unit}")

