    if not tentative:
        if not iface.providedBy(candidate):
            raise zope.interface.Invalid("Candidate does not provide the interface")
    for name, spec in iface.getMethodSpecifications():
        if not hasattr(candidate, name):
            raise zope.interface.Invalid("Candidate does not define method {}".format(name))
        method = getattr(candidate, name)
        if not spec.isValid(method):
            raise zope.interface.Invalid("Method {} does not have the correct signature".format(name))
    for name, spec in iface.getAttributeSpecifications():
        if not hasattr(candidate, name):
            raise zope.interface.Invalid("Candidate does not define attribute {}".format(name))
        attribute = getattr(candidate, name)
        if not spec.isValid(attribute):
            raise zope.interface.Invalid("Attribute {} does not have the correct type".format(name))
    return True

